import React from 'react';
import { useLocation } from 'react-router-dom';
import HeaderShop from '../../components/E-Commerce/AllProducts/HeaderShop';
import Cart from '../../components/E-Commerce/Cart';
import Preloader from '../../helper/Preloader';
import FooterOne from '../../components/FooterOne';
import { SEO } from "../../utils/SEO";

const CartPage = () => {
  const location = useLocation();
  const queryParams = new URLSearchParams(location.search);
  const searchParam = queryParams.get('search') || '';
    const can = window.location.href;
  return (
    <>
      <SEO
        // title="4ceps | Your Cart – Review Healthcare Services"
        // description="Check your selected healthcare services in the 4ceps cart. Review details and proceed to book your appointment quickly and easily."
        url={can}
      /> 
      <Preloader />
      <HeaderShop initialSearchQuery={searchParam} />
      <Cart />
      <FooterOne />
    </>
  );
};

export default CartPage;
